  if (mediaType !== 'application/json') return bodyError('Content-Type must be application/json');
  if (raw === null) return bodyError(`body must be at most ${MAX_BODY_BYTES} bytes`);

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return bodyError('body must be valid JSON');
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    return bodyError('body must be a JSON object');
  }

  const body = parsed as Record<string, unknown>;
  const fields: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (!FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  let input = '';
  if (!Object.hasOwn(body, 'input')) {
    fields.push({ field: 'input', message: 'is required' });
  } else {
    const v = body.input;
    if (typeof v !== 'string') fields.push({ field: 'input', message: 'must be a string' });
    else if (v.length < 1 || v.length > 1000) fields.push({ field: 'input', message: 'must be 1 to 1000 characters' });
    else if (v.trim() === '') fields.push({ field: 'input', message: 'must not be only whitespace' });
    else input = v;
  }

  const steps = intField(body, 'steps', 1, 20, 5, fields);
  const failAttempts = intField(body, 'failAttempts', 0, 5, 0, fields);
  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input, steps, failAttempts } };
}

