import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';
import { getJobRow, insertJob, listJobRows, openDatabase, toJob, transaction } from './db.ts';
import { KEY_RE, MAX_BODY_BYTES, parseSubmission, type FieldError } from './validate.ts';

const HEARTBEAT_FRESH_MS = 3000;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

/** Reads the request body, or resolves null if it exceeds MAX_BODY_BYTES. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const raw = await readBody(req);

  const keyHeader = req.headers['idempotency-key'];
  const keyErrors: FieldError[] = [];
  let key: string | undefined;
  if (keyHeader !== undefined) {
    if (typeof keyHeader === 'string' && KEY_RE.test(keyHeader)) key = keyHeader;
    else keyErrors.push({ field: 'Idempotency-Key', message: 'must be 1 to 128 letters, digits, "_" or "-"' });
  }

  const parsed = parseSubmission(req.headers['content-type'], raw);
  if (!parsed.ok || keyErrors.length > 0) {
    const fields = [...(parsed.ok ? [] : parsed.fields), ...keyErrors];
    sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
    return;
  }
  const v = parsed.value;

  if (key === undefined) {
    const id = randomUUID();
    transaction(db, () => insertJob(db, id, v.input, v.steps, v.failAttempts));
    send(res, 201, toJob(getJobRow(db, id)!));
    return;
  }

  const fingerprint = JSON.stringify([v.input, v.steps, v.failAttempts]);
  const outcome = transaction(db, () => {
    const existing = db.prepare('SELECT fingerprint, job_id FROM idempotency WHERE key = ?').get(key) as unknown as
      | { fingerprint: string; job_id: string }
      | undefined;
    if (existing) {
      const job = getJobRow(db, existing.job_id)!;
      return { kind: existing.fingerprint === fingerprint ? ('replay' as const) : ('conflict' as const), job };
    }
    const id = randomUUID();
    insertJob(db, id, v.input, v.steps, v.failAttempts);
    db.prepare('INSERT INTO idempotency (key, fingerprint, job_id) VALUES (?, ?, ?)').run(key, fingerprint, id);
    return { kind: 'created' as const, job: getJobRow(db, id)! };
  });

  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  } else {
    send(res, outcome.kind === 'created' ? 201 : 200, toJob(outcome.job));
  }
}

function handleHealth(_req: IncomingMessage, res: ServerResponse, database: DatabaseSync): void {
  const row = database.prepare("SELECT at_ms FROM heartbeats WHERE name = 'worker'").get() as unknown as
    | { at_ms: number }
    | undefined;
  const up = row !== undefined && Date.now() - Number(row.at_ms) <= HEARTBEAT_FRESH_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

const JOB_PATH = /^\/api\/jobs\/([^/]+)$/;

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/health') {
    if (method !== 'GET') return sendError(res, 405, 'method_not_allowed', 'Method not allowed.');
    return handleHealth(req, res, db);
  }
  if (pathname === '/') {
    if (method !== 'GET') return sendError(res, 405, 'method_not_allowed', 'Method not allowed.');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return send(res, 200, { jobs: listJobRows(db).map(toJob) });
    if (method === 'POST') return handleCreate(req, res);
    return sendError(res, 405, 'method_not_allowed', 'Method not allowed.');
  }
  const match = JOB_PATH.exec(pathname);
  if (match) {
    if (method !== 'GET') return sendError(res, 405, 'method_not_allowed', 'Method not allowed.');
    const row = getJobRow(db, match[1]!);
    if (!row) return sendError(res, 404, 'not_found', 'No job with that id.');
    return send(res, 200, toJob(row));
  }
  sendError(res, 404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  const force = setTimeout(() => process.exit(0), 3000);
  force.unref();
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

