import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';

const STEP_MS = 100;
const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 1000;
const MAX_ATTEMPTS = 3;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

interface ClaimedJob {
  id: string;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
}

// Jobs left `running` by a worker that died are queued again; their interrupted attempt stays counted.
db.prepare("UPDATE jobs SET status = 'queued', run_after = 0, updated_at = ? WHERE status = 'running'").run(
  new Date().toISOString(),
);

const beat = () =>
  db
    .prepare(
      "INSERT INTO heartbeats (name, at_ms) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at_ms = excluded.at_ms",
    )
    .run(Date.now());
beat();
const heartbeatTimer = setInterval(beat, HEARTBEAT_MS);

const claimStmt = db.prepare(`
  UPDATE jobs
  SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ?
  WHERE seq = (
    SELECT seq FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1
  )
  RETURNING id, input, steps, fail_attempts, attempts`);

function claim(): ClaimedJob | undefined {
  const now = Date.now();
  return claimStmt.get(new Date(now).toISOString(), now) as unknown as ClaimedJob | undefined;
}

function setProgress(id: string, completed: number): void {
  db.prepare('UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ?').run(completed, new Date().toISOString(), id);
}

function finishCompleted(job: ClaimedJob): void {
  db.prepare(
    `UPDATE jobs SET status = 'completed', completed = steps, output = ?, error = NULL, updated_at = ? WHERE id = ?`,
  ).run(job.input.toUpperCase(), new Date().toISOString(), job.id);
}

function finishFailed(job: ClaimedJob): void {
  db.prepare(`UPDATE jobs SET status = 'failed', error = 'transient failure', output = NULL, updated_at = ? WHERE id = ?`).run(
    new Date().toISOString(),
    job.id,
  );
}

function requeue(job: ClaimedJob): void {
  const delay = 250 + Math.floor(Math.random() * 1751); // 250..2000 ms
  db.prepare(`UPDATE jobs SET status = 'queued', run_after = ?, updated_at = ? WHERE id = ?`).run(
    Date.now() + delay,
    new Date().toISOString(),
    job.id,
  );
}

/** Runs one attempt. Returns early without changing the job if the worker is stopping. */
async function runAttempt(job: ClaimedJob): Promise<void> {
  if (job.attempts <= job.fail_attempts) {
    await sleep(STEP_MS);
    if (stopping) return;
    if (job.attempts >= MAX_ATTEMPTS) finishFailed(job);
    else requeue(job);
    return;
  }
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return;
    setProgress(job.id, step);
  }
  finishCompleted(job);
}

console.log('worker started');
while (!stopping) {
  let job: ClaimedJob | undefined;
  try {
    job = claim();
  } catch (err) {
    console.error('claim failed:', err);
  }
  if (!job) {
    await sleep(IDLE_POLL_MS);
    continue;
  }
  try {
    await runAttempt(job);
  } catch (err) {
    console.error(`attempt for job ${job.id} failed:`, err);
  }
}

clearInterval(heartbeatTimer);
db.close();
console.log('worker stopped');

